package net.officefloor.hq.app.grade;

import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The grades a person may be given on a sheet: A, B and C, less those retired there. A person on a
 *  retired grade keeps it, but no one can be given it any more. */
@Service
public class GradeService {

    /** Every grade, in order. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    private final RetiredGradeRepository retired;
    private final SheetService sheets;
    private final Audit audit;

    public GradeService(RetiredGradeRepository retired, SheetService sheets, Audit audit) {
        this.retired = retired;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's retired grades. */
    public Set<String> retired(String sheetId) {
        return retired.findBySheetIdOrderByGradeAsc(sheetId).stream().map(RetiredGrade::getGrade)
                .collect(Collectors.toSet());
    }

    /** Whether the grade is retired on the sheet. */
    public boolean isRetired(String sheetId, String grade) {
        return retired.existsBySheetIdAndGrade(sheetId, grade);
    }

    /** Refuse a retired grade chosen for a person. */
    public void requireChoosable(String sheetId, String grade) {
        if (isRetired(sheetId, grade)) {
            throw new GradeRetiredException("The grade " + grade + " is retired");
        }
    }

    /** Retire a grade on the sheet. Refused when it is not a grade or is retired already; the sheet
     *  is held locked so the same grade retired at the same moment is checked against itself. */
    @Transactional
    public void retire(String sheetId, String user, String grade) {
        if (!GRADES.contains(grade)) {
            throw new GradeRetiredException("There is no grade " + grade);
        }
        sheets.lock(sheetId);
        if (isRetired(sheetId, grade)) {
            throw new GradeRetiredException("The grade " + grade + " is retired already");
        }
        retired.saveAndFlush(new RetiredGrade(sheetId, grade));
        audit.recordOnCommit("GRADE_RETIRED sheet=" + sheetId + " by=" + user + " grade=" + grade);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Set;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Gives a selection of people a grade together. */
@Service
public class BulkGradeService {

    private final PersonRepository people;
    private final PersonService service;
    private final RollupService rollups;
    private final SettingService settings;
    private final SheetService sheets;

    public BulkGradeService(PersonRepository people, PersonService service, RollupService rollups,
            SettingService settings, SheetService sheets) {
        this.people = people;
        this.service = service;
        this.rollups = rollups;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Give each selected person, in list order, the grade from a date
     *  (null takes the sheet's today) exactly as saving them from the editor with their name and terms
     *  unchanged would, each followed by the figures it moved. Refused as a whole, writing nothing,
     *  when any selected person is not on the sheet. A viewer, or anyone on an archived sheet, gives
     *  no one the grade. */
    @Transactional
    public List<Person> give(String sheetId, String user, Set<Long> ids, String grade, LocalDate from) {
        List<Person> selected = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(person -> ids.contains(person.getId())).toList();
        if (selected.size() != ids.size()) {
            throw new NoSuchElementException("Not every selected person is on sheet " + sheetId);
        }
        List<Person> graded = new ArrayList<>();
        if (settings.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            // A viewer, or anyone on an archived sheet, changes nothing: no selected person is graded.
            return graded;
        }
        for (Person person : selected) {
            graded.add(rollups.track(sheetId, user, () -> service.update(sheetId, user, person.getId(),
                    person.getVersion(), person.getName(), grade, from,
                    service.termsOn(person, sheets.today(sheetId)), person.getContact())));
        }
        return graded;
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;
import net.officefloor.hq.app.history.History;
import org.springframework.stereotype.Service;

/** The grades given to the people on a sheet, each in force from its from-date. */
@Service
public class PersonGradeService {

    /** Grades from the earliest: no from-date first, then by from-date. */
    private static final Comparator<PersonGrade> FROM_EARLIEST =
            Comparator.comparing(PersonGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()));

    private final PersonGradeRepository grades;
    private final History history;

    public PersonGradeService(PersonGradeRepository grades, History history) {
        this.grades = grades;
        this.history = history;
    }

    /** A person's grades, from the earliest. */
    public List<PersonGrade> of(Long personId) {
        return grades.findByPersonId(personId).stream().sorted(FROM_EARLIEST).toList();
    }

    /** Each person's grades on the sheet, from the earliest, by person id. */
    public Map<Long, List<PersonGrade>> bySheet(String sheetId) {
        return grades.findBySheetId(sheetId).stream().sorted(FROM_EARLIEST)
                .collect(Collectors.groupingBy(PersonGrade::getPersonId));
    }

    /** Each person's grades on the sheet as they stood at the end of a day, from the earliest, by
     *  person id (null: as they stand now). */
    public Map<Long, List<PersonGrade>> bySheet(String sheetId, LocalDate asOf) {
        if (asOf == null) {
            return bySheet(sheetId);
        }
        return bySheet(sheetId).keySet().stream().collect(Collectors.toMap(id -> id,
                id -> history.grades(id, asOf).stream().sorted(FROM_EARLIEST).toList()));
    }

    /** The person's grade in force on a date: the one whose from-date is the latest on or before it
     *  (the first grade applies from the beginning of time). */
    public String gradeOn(Long personId, LocalDate date) {
        return gradeOn(of(personId), date);
    }

    /** The person's grade in force on a date as their grades stood at the end of a day (null: as
     *  they stand now). */
    public String gradeOn(Long personId, LocalDate date, LocalDate asOf) {
        return gradeOn(asOf == null ? of(personId) : history.grades(personId, asOf), date);
    }

    /** The grade in force on a date among a person's grades; null when they have none. */
    public static String gradeOn(List<PersonGrade> theirs, LocalDate date) {
        return theirs.stream()
                .filter(g -> g.appliesOn(date))
                .max(FROM_EARLIEST)
                .map(PersonGrade::getGrade)
                .orElse(null);
    }

    /** Give a person a grade from a date (null: from the beginning of time), replacing the one they
     *  had from that date and keeping the others. */
    public PersonGrade give(Person person, String grade, LocalDate from) {
        Optional<PersonGrade> had = from == null
                ? grades.findByPersonIdAndFromIsNull(person.getId())
                : grades.findByPersonIdAndFrom(person.getId(), from);
        PersonGrade given = had
                .map(existing -> {
                    existing.setGrade(grade);
                    return existing;
                })
                .orElseGet(() -> new PersonGrade(person.getSheetId(), person.getId(), grade, from));
        return grades.saveAndFlush(given);
    }
}

